import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第三册：培养技能 · Lesson 5 The facts","description":"学习 间接疑问句的陈述语序，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 5 The facts","description":"学习 间接疑问句的陈述语序，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 间接疑问句的陈述语序，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 4 The double life of Alfred Bloggs","link":"/life/english/new-concept/book-3/unit-01/lesson-004"},"next":{"text":"第三册：培养技能 · Lesson 6 Smash-and-grab","link":"/life/english/new-concept/book-3/unit-01/lesson-006"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 4 The double life of Alfred Bloggs","link":"/life/english/new-concept/book-3/unit-01/lesson-004"},"next":{"text":"第三册：培养技能 · Lesson 6 Smash-and-grab","link":"/life/english/new-concept/book-3/unit-01/lesson-006"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/lesson-005.md","filePath":"life/english/new-concept/book-3/unit-01/lesson-005.md"}'),i={name:"life/english/new-concept/book-3/unit-01/lesson-005.md"};function l(s,e,r,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-5-the-facts" tabindex="-1">第三册：培养技能 · Lesson 5 The facts <a class="header-anchor" href="#第三册-培养技能-·-lesson-5-the-facts" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 5 The facts&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从新闻核实和数字准确性进入间接引语，练习把采访内容转换成书面报道。数字、单位和信息来源应一起交代；即使语法正确，也不能让推测变成事实。目标是分清一般陈述、疑问转述和要求转述，保留原话的语气与真实性边界。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>verify</td><td>/ˈverɪfaɪ/</td><td>v.</td><td>核实</td><td>verify a figure</td></tr><tr><td>source</td><td>/sɔːs/</td><td>n.</td><td>来源</td><td>a reliable source</td></tr><tr><td>estimate</td><td>/ˈestɪmət/</td><td>n.</td><td>估计</td><td>a rough estimate</td></tr><tr><td>accurate</td><td>/ˈækjərət/</td><td>adj.</td><td>准确的</td><td>accurate information</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>check with — 向某人核实</li><li>on record — 公开记录在案</li></ul><h2 id="语法讲解-间接疑问句的陈述语序" tabindex="-1">语法讲解：间接疑问句的陈述语序 <a class="header-anchor" href="#语法讲解-间接疑问句的陈述语序" aria-label="Permalink to &quot;语法讲解：间接疑问句的陈述语序&quot;">​</a></h2><p>转述问题时，疑问词之后通常使用主语加谓语的陈述语序，不能保留直接问句的倒装。一般疑问句用 whether 或 if 引出。主句用过去时，转述动词常向过去移动，但仍然有效的事实未必必须后移；时间地点和人称要依叙述视角调整。ask 后可以接人再接从句，不能把 ask 的宾语遗漏导致对象不清。报道数字时还应保留 about、at least 等限定，转述语法本身并不增加信息准确度。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The editor asked how many households the survey had covered.</p></blockquote><p>编辑问这项调查覆盖了多少户家庭。</p><p>how many households 为 covered 的宾语，the survey 为主语；had covered 表示调查在询问之前已进行。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>The editor asked how many households had the survey covered 错在保留问句倒装，间接疑问从句要恢复陈述语序。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>先读直接问句 Did the total include volunteers?，再读 I asked whether the total included volunteers，比较助动词消失后的节奏。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I asked whether the total included volunteers. The organizer said that it did. We changed the headline to distinguish guests from staff.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一段核实活动人数的编辑记录，包含一个间接疑问句和一次更正。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>whether 引出核实问题；最后一句说明核实如何影响报道。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>改写：She asked, “Is the figure final?”</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She asked whether the figure was final.</p><p><strong>解析：</strong> 一般疑问转述用 whether，语序为主语加谓语。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>例句中谁进行了调查覆盖？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> the survey</p><p><strong>解析：</strong> 这是从句的语法主语。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>about 300 能否直接转述为 exactly 300？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不能。</p><p><strong>解析：</strong> 这会改变原信息的精确程度。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：间接疑问句的陈述语序。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-004">上一课</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-01/lesson-006">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=a(i,[["render",l]]);export{p as __pageData,f as default};
